{
  "name": "rf_read_trim_data",
  "confidence": "medium",
  "docstring": "Reads RF trim/calibration values from fuse/MMIO status paths, clamps and stores them into the global trim structure, and marks the loaded data as valid.",
  "subsystem": "rf",
  "var_renames": {
    "v0": "trim_base",
    "v2": "trim_mode_flag",
    "v3": "trim_level_clamped",
    "v4": "xtal_ftune",
    "v5": "temp_trim_raw",
    "v6": "temp_trim_clamped",
    "_frame.v8": "temp_trim_raw",
    "_frame.v9": "bus_value32",
    "_frame.v10": "mmio_value64"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "trim data valid/done flag"
    },
    {
      "offset": 2,
      "meaning": "temperature trim/calibration byte"
    },
    {
      "offset": 3,
      "meaning": "trim status byte set to 0x80 after load"
    },
    {
      "offset": 4,
      "meaning": "clipped RF trim level (max 31 when present, 15 otherwise)"
    },
    {
      "offset": 6,
      "meaning": "xtal frequency trim value"
    }
  ]
}
